mapper.insert:
INSERT INTO cart_item(
    cart_id,
    product_id,
    quantity
) VALUES (
    #{cartId},
    #{productId},
    #{quantity}
)

mapper.update:
UPDATE cart_item
SET quantity = quantity + #{quantity}, updated_at = NOW()
WHERE cart_item_id = #{cartItemId}

mapper.delete:
DELETE ci
FROM cart_item ci
JOIN cart c
    ON ci.cart_id = c.cart_id
WHERE ci.cart_item_id = #{cartItemId}
AND c.member_id = #{memberId}
